<section class="mt-7 flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-extrabold">Audience</h2><p class="text-sm text-[#78908c]">Import, organize, segment and clean contacts.</p></div><button onclick="document.getElementById('addDialog').showModal()" class="btn btn-primary"><i data-lucide="user-plus" class="h-4"></i>Add contact</button></section>
<section class="card mt-6 p-5"><div class="flex flex-wrap gap-3"><form class="flex flex-1 gap-2"><input name="q" value="<?= esc($q) ?>" class="field min-w-48" placeholder="Search contacts…"><button class="btn shadow-soft">Search</button></form><form action="<?= base_url('contacts/import') ?>" method="post" enctype="multipart/form-data" class="flex gap-2"><?= csrf_field() ?><input name="contacts_file" type="file" accept=".csv" required class="field max-w-64 text-sm"><button class="btn shadow-soft">Import CSV</button></form><form action="<?= base_url('contacts/delete-duplicates') ?>" method="post"><?= csrf_field() ?><button class="btn text-[#b25d43] shadow-soft">Remove duplicates</button></form></div><div class="mt-5 overflow-x-auto"><table class="w-full min-w-[680px] text-left text-sm"><thead class="text-[10px] uppercase text-[#879e9a]"><tr><th class="pb-3">Contact</th><th>Status</th><th>Source</th><th>Birthday</th><th>Added</th></tr></thead><tbody class="divide-y divide-[#dbeae7]"><?php foreach($contacts as $c): ?><tr><td class="py-4 font-bold"><?= esc(trim($c['first_name'].' '.$c['last_name'])) ?><p class="text-xs font-normal text-[#78908c]"><?= esc($c['email']) ?></p></td><td><span class="rounded-full bg-[#dff4e9] px-2 py-1 text-xs font-bold text-[#25775f]"><?= esc($c['status']) ?></span></td><td><?= esc(strtoupper($c['source'])) ?></td><td><?= esc($c['birthday'] ?: '—') ?></td><td><?= esc(date('M j, Y',strtotime($c['created_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><div class="mt-4"><?= $pager->links() ?></div></section>
<dialog id="addDialog" class="w-full max-w-md rounded-3xl bg-mist p-6 shadow-2xl backdrop:bg-[#153b39]/30"><div class="flex justify-between"><h3 class="text-xl font-extrabold">Add contact</h3><button onclick="this.closest('dialog').close()"><i data-lucide="x"></i></button></div><form action="<?= base_url('contacts/create') ?>" method="post" class="mt-5 space-y-3"><?= csrf_field() ?><input name="email" type="email" required class="field" placeholder="Email address"><div class="grid grid-cols-2 gap-3"><input name="first_name" class="field" placeholder="First name"><input name="last_name" class="field" placeholder="Last name"></div><input name="phone" class="field" placeholder="Phone"><input name="birthday" type="date" class="field"><button class="btn btn-primary w-full justify-center">Save contact</button></form></dialog>
